               <span class="required" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="field-help">Select one option before saving your preference.</p>
             <p id="notification-error" class="field-error" hidden>Error: Select how you prefer to receive notifications.</p>

             <div class="options">
               <div class="option">
                 <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                 <label for="notification-email">Email</label>
               </div>

