   <script>
     const form = document.getElementById("notification-form");
     const fieldset = document.getElementById("notification-fieldset");
     const radios = Array.from(form.elements.namedItem("notificationPreference"));
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("status-message");

     function updateGroupDescribedBy(hasError) {
       fieldset.setAttribute(
         "aria-describedby",
         hasError ? "notification-help notification-error" : "notification-help"
       );
     }

     function setErrorState(hasError) {
       errorMessage.hidden = !hasError;
       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", hasError ? "true" : "false");
       });
       updateGroupDescribedBy(hasError);
     }

     form.addEventListener("submit", (event) => {
       const selectedRadio = radios.find((radio) => radio.checked);

       if (!selectedRadio) {
         event.preventDefault();
         setErrorState(true);
         statusMessage.textContent = "";
         radios[0].focus();
         return;
       }

       event.preventDefault();
       setErrorState(false);
       statusMessage.textContent = "Preference saved: " + selectedRadio.value + ".";
     });

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         if (radio.checked) {
           setErrorState(false);
         }
       });
     });
